from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    uniform_rows = {}
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            uniform_rows[r] = row[0]

    uniform_cols = {}
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            uniform_cols[c] = next(iter(vals))

    # The repeated full-length lines are the separators.
    row_sep_color = Counter(uniform_rows.values()).most_common(1)[0][0] if uniform_rows else None
    col_sep_color = Counter(uniform_cols.values()).most_common(1)[0][0] if uniform_cols else None
    row_seps = {r for r, color in uniform_rows.items() if color == row_sep_color}
    col_seps = {c for c, color in uniform_cols.items() if color == col_sep_color}

    def intervals(n, seps):
        result, start = [], 0
        for i in range(n):
            if i in seps:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    row_blocks = intervals(h, row_seps)
    col_blocks = intervals(w, col_seps)

    excluded = row_seps | col_seps
    colors = Counter(
        grid[r][c]
        for r in range(h) if r not in row_seps
        for c in range(w) if c not in col_seps
    )
    background = colors.most_common(1)[0][0]
    separator_colors = set(uniform_rows.values()) | set(uniform_cols.values())

    blocks = []
    for r0, r1 in row_blocks:
        row = []
        for c0, c1 in col_blocks:
            marks = [
                (r - r0, c - c0)
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != background and grid[r][c] not in separator_colors
            ]
            row.append(marks)
        blocks.append(row)

    counts = [len(marks) for row in blocks for marks in row]
    all_single = bool(counts) and all(n == 1 for n in counts)

    out = []
    for row in blocks:
        outrow = []
        for marks in row:
            selected = len(marks) == 2
            # In the all-single-marker pattern, mark the uniquely specified
            # within-block location.
            if all_single:
                selected = marks == [(3, 2)]
            outrow.append(1 if selected else background)
        out.append(outrow)
    return out
